impl Solution {
    pub fn length_of_lis(nums: Vec<i32>) -> i32 {
        let mut subseq = Vec::new();
        for num in nums {
            // Binary search for the position to replace or append
            match subseq.binary_search(&num) {
                Ok(_) => continue, // num already in subseq, skip
                Err(pos) => {
                    if pos == subseq.len() {
                        subseq.push(num);
                    } else {
                        subseq[pos] = num;
                    }
                }
            }
        }
        subseq.len() as i32
    }
}

